{
  "name": "@tanstack/vue-table",
  "version": "9.3.1",
  "description": "Headless UI for building powerful tables & datagrids for Vue.",
  "author": "Tanner Linsley",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/TanStack/table.git",
    "directory": "packages/vue-table"
  },
  "homepage": "https://tanstack.com/table",
  "funding": {
    "type": "github",
    "url": "https://github.com/sponsors/tannerlinsley"
  },
  "keywords": [
    "vue",
    "table",
    "vue-table",
    "datagrid",
    "tanstack-intent"
  ],
  "type": "module",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": "./dist/index.js",
    "./experimental-worker-plugin": "./dist/experimental-worker-plugin.js",
    "./flex-render": "./dist/flex-render.js",
    "./static-functions": "./dist/static-functions.js",
    "./package.json": "./package.json"
  },
  "sideEffects": false,
  "engines": {
    "node": ">=20"
  },
  "files": [
    "dist",
    "skills"
  ],
  "scripts": {
    "clean": "rimraf ./build && rimraf ./dist",
    "test:eslint": "eslint ./src",
    "test:lib": "vitest --passWithNoTests",
    "test:lib:dev": "pnpm test:lib --watch",
    "test:types": "tsc",
    "test:build": "publint --strict",
    "build": "tsdown"
  },
  "dependencies": {
    "@tanstack/store": "^0.11.2",
    "@tanstack/table-core": "workspace:*"
  },
  "devDependencies": {
    "@testing-library/vue": "^8.1.0",
    "@vitejs/plugin-vue": "^6.0.9",
    "eslint-plugin-vue": "^10.11.1",
    "vue": "^3.5.43"
  },
  "peerDependencies": {
    "vue": ">=3.2"
  }
}
